38:     google::protobuf::FieldDescriptor const& parameter) {
39:   // This hash is not intended to be comprehensive. Problematic types and their
40:   // includes should be added as needed.
41:   static auto const* const kTypeIncludeMap =
42:       new std::unordered_map<std::string, std::string>(
43:           {{"google.protobuf.Duration", "google/protobuf/duration.pb.h"}});
44:   if (parameter.type() == google::protobuf::FieldDescriptor::TYPE_MESSAGE) {
45:     auto iter = kTypeIncludeMap->find(parameter.message_type()->full_name());
46:     if (iter != kTypeIncludeMap->end()) {
47:       return iter->second;
48:     }
49:   }
50:   return {};
51: }
