129: bool ServiceCodeGenerator::HasMessageWithMapField() const {
130:   for (auto method : methods_) {
131:     auto const* const request = method.get().input_type();
132:     auto const* const response = method.get().output_type();
133:     for (int j = 0; j < request->field_count(); ++j) {
134:       if (request->field(j)->is_map()) {
135:         return true;
136:       }
137:     }
138:     for (int k = 0; k < response->field_count(); ++k) {
139:       if (response->field(k)->is_map()) {
140:         return true;
141:       }
142:     }
143:   }
144:   return false;
145: }
