31: /**
32:  * Wrapper around a google::protobuf::io::ZeroCopyOutputStream and a
33:  * google::protobuf::io::Printer object so that they can be used for
34:  * code generation.
35:  */
36: class Printer {
37:  public:
38:   Printer() = default;
39:   Printer(google::protobuf::compiler::GeneratorContext* generator_context,
40:           std::string const& file_name)
41:       : output_(generator_context->Open(file_name)),
42:         printer_(std::make_unique<google::protobuf::io::Printer>(
43:             output_.get(), '$', nullptr)) {}
44: 
45:   Printer(Printer const&) = delete;
46:   Printer& operator=(Printer const&) = delete;
47:   Printer(Printer&&) = default;
48:   Printer& operator=(Printer&&) = default;
49: 
50:   /**
51:    * Print some text after applying variable substitutions.
52:    *
53:    * If a particular variable in the text is not defined, this will crash.
54:    * Variables to be substituted are identified by their names surrounded by
55:    * delimiter characters (as given to the constructor).  The variable bindings
56:    * are defined by the given map.
57:    */
58:   void Print(VarsDictionary const& variables, std::string const& text) {
59:     printer_->Print(variables, text.c_str());
60:   }
61: 
62:   /**
63:    * Like the first Print(), except the substitutions are given as parameters.
