void ReplaceAll(std::string& text, std::string const& from,
                std::string const& to) {
  for (std::string::size_type pos = 0;
       (pos = text.find(from, pos)) != std::string::npos; pos += to.size()) {
    text.replace(pos, from.size(), to);
  }
}

std::string LroOperationSupport(std::string text, bool grpc_operation) {
  ReplaceAll(text, "$lro_operation_response_type$",
             grpc_operation ? "google::longrunning::Operation"
